parameters.filterByFormula:
={{ (() => {
  const termino = String($fromAI(
    'busqueda',
    'Una palabra o fragmento del producto, origen o presentación solicitados; conservá las tildes. Ejemplo: Colombia. Para una consulta general, cadena vacía. Nunca escribas fórmulas.',
    'string'
  ) ?? '').trim().toLowerCase();

  return termino
    ? `FIND(${JSON.stringify(termino)},LOWER({Producto}&" "&{Categoría o colección}&" "&{Marca}&" "&{Descripción breve}&" "&{Variantes y opciones}))>0`
    : 'TRUE()';
})() }}

parameters.message:
={{ JSON.stringify({
  estado: 'Tarea completada: respuesta al usuario emitida',
  ejecucion: $execution.id,
  herramientas: ($('AGENTE RITUAL').first().json.intermediateSteps ?? []).map(paso => ({
    herramienta: paso.action?.tool,
    resultado: paso.observation
  }))
}, null, 2) }}
